    {index=57,address="0x0838DBB4",op=227,arg_byte=0,arg_short=5,arg1=0,arg2=0,handler="sync.await",pointer=false},
    {index=58,address="0x0838DBCC",op=145,arg_byte=8,arg_short=10,arg1=4,arg2=0,handler="actor.rotate",pointer=false},
    {index=59,address="0x0838DBE4",op=46,arg_byte=15,arg_short=1,arg1=0,arg2=0,handler="portrait.set",pointer=false},
    {index=60,address="0x0838DBFC",op=207,arg_byte=2,arg_short=40,arg1=1,arg2=0,handler="dialogue.variable",pointer=false},
    {index=61,address="0x0838DC14",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08392404",fr={block="0x08392404",address="0x083924A3",raw="20c7617e326320637e323765737420746120234335426fee7465206175780a6c65747472657323522e2357205475207920726563657672617320646573206c6574747265730a647e323761757472657320506f6be96d6f6e2e",text=" Ça~2c c~27est ta #C5Boîte aux\nlettres#R.#W Tu y recevras des lettres\nd~27autres Pokémon."}},
    {index=62,address="0x0838DC2C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08392228",fr={block="0x08392228",address="0x083922D1",raw="20c7617e326320637e323765737420746120234335426fee7465206175780a6c65747472657323522e235720437e3237657374206963692071757e3237657374206c697672e9206c6520636f7572726965720a717565206c65732061757472657320506f6be96d6f6e20747e3237656e766f69656e742e",text=" Ça~2c c~27est ta #C5Boîte aux\nlettres#R.#W C~27est ici qu~27est livré le courrier\nque les autres Pokémon t~27envoient."}},
    {index=63,address="0x0838DC44",op=48,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.clear",pointer=false},
    {index=64,address="0x0838DC5C",op=228,arg_byte=0,arg_short=6,arg1=0,arg2=0,handler="sync.alert",pointer=false},
    {index=65,address="0x0838DC74",op=227,arg_byte=0,arg_short=5,arg1=0,arg2=0,handler="sync.await",pointer=false},
    {index=66,address="0x0838DC8C",op=45,arg_byte=9,arg_short=2,arg1=54,arg2=0,handler="portrait.configure",pointer=false},
    {index=67,address="0x0838DCA4",op=207,arg_byte=2,arg_short=40,arg1=1,arg2=0,handler="dialogue.variable",pointer=false},
    {index=68,address="0x0838DCBC",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08392120",fr={block="0x08392120",address="0x0839218B",raw="2054752074652072617070656c6c65732063657474650a63726576617373652064616e73206c617175656c6c6520246e32206573740a746f6d62e93f",text=" Tu te rappelles cette\ncrevasse dans laquelle $n2 est\ntombé?"}},
    {index=69,address="0x0838DCD4",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391FDC",fr={block="0x08391FDC",address="0x08392064",raw="20496c2079206120706c65696e20647e32376175747265730a636174617374726f70686573206e61747572656c6c6573206465206365207479706520656e2063650a6d6f6d656e742e",text=" Il y a plein d~27autres\ncatastrophes naturelles de ce type en ce\nmoment."}},
    {index=70,address="0x0838DCEC",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391EA8",fr={block="0x08391EA8",address="0x08391F17",raw="204465206e6f6d627265757820506f6be96d6f6e0a736f75666672656e742064652063657320636174617374726f706865732e",text=" De nombreux Pokémon\nsouffrent de ces catastrophes."}},
    {index=71,address="0x0838DD04",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391DEC",fr={block="0x08391DEC",address="0x08391E32",raw="204574206d6f697e3263206a652076657578206169646572206365730a506f6be96d6f6e2e",text=" Et moi~2c je veux aider ces\nPokémon."}},
    {index=72,address="0x0838DD1C",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391C8C",fr={block="0x08391C8C",address="0x08391D07",raw="204a65207665757820616964657220e02066616972652064652063650a6d6f6e646520756e206c696575206ff920746f7573206c657320506f6be96d6f6e0a7075697373656e7420766976726520656e2073e96375726974e92e",text=" Je veux aider à faire de ce\nmonde un lieu où tous les Pokémon\npuissent vivre en sécurité."}},
    {index=73,address="0x0838DD34",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391AC0",fr={block="0x08391AC0",address="0x08391B7A",raw="2045747e3263206575682e2e2e235720617072e8732061766f69722076750a636f6d6d656e74207475206173207365636f75727520246e327e3263206a650a63726f69732071756520747520706f757272616973206d7e323761696465722e",text=" Et~2c euh...#W après avoir vu\ncomment tu as secouru $n2~2c je\ncrois que tu pourrais m~27aider."}},
    {index=74,address="0x0838DD4C",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x083919C0",fr={block="0x083919C0",address="0x08391A20",raw="20c76120746520646972616974206465206d6f6e74657220756e650ae97175697065206465207365636f7572732061766563206d6f693f",text=" Ça te dirait de monter une\néquipe de secours avec moi?"}},
    {index=75,address="0x0838DD64",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x083918CC",fr={block="0x083918CC",address="0x0839192D",raw="2054752074652072617070656c6c6573206465206c610a63726576617373652064616e73206c617175656c6c6520246e3220610a63687574e93f",text=" Tu te rappelles de la\ncrevasse dans laquelle $n2 a\nchuté?"}},
    {index=76,address="0x0838DD7C",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391798",fr={block="0x08391798",address="0x0839180F",raw="204568206269656e20696c2079206120657520746f757465730a736f7274657320646520636174617374726f70686573206e61747572656c6c65730a73696d696c61697265732072e963656d6d656e742e",text=" Eh bien il y a eu toutes\nsortes de catastrophes naturelles\nsimilaires récemment."}},
    {index=77,address="0x0838DD94",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391654",fr={block="0x08391654",address="0x083916C5",raw="2042656175636f757020646520506f6be96d6f6e0a736f75666672656e742064652063657320636174617374726f70686573206e61747572656c6c65732e",text=" Beaucoup de Pokémon\nsouffrent de ces catastrophes naturelles."}},
    {index=78,address="0x0838DDAC",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391524",fr={block="0x08391524",address="0x08391593",raw="204a652076657578206661697265206c65206269656e2e0a4a652076657578206169646572206c657320506f6be96d6f6e2e",text=" Je veux faire le bien.\nJe veux aider les Pokémon."}},
    {index=79,address="0x0838DDC4",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x083913E8",fr={block="0x083913E8",address="0x08391465",raw="204a65207665757820717565206c657320506f6be96d6f6e0a7075697373656e742073652073656e74697220656e2073e96375726974e92e",text=" Je veux que les Pokémon\npuissent se sentir en sécurité."}},
    {index=80,address="0x0838DDDC",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391250",fr={block="0x08391250",address="0x083912ED",raw="20416c6f72737e32632068756d2e2e2e2357204568206269656e7e3263206a7e323761690a707520766f697220636f6d6d652074752074652064e962726f75696c6c616973206269656e0a7175616e64206f6e2061207365636f75727520246e322e2e2e",text=" Alors~2c hum...#W Eh bien~2c j~27ai\npu voir comme tu te débrouillais bien\nquand on a secouru $n2..."}},
    {index=81,address="0x0838DDF4",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08391138",fr={block="0x08391138",address="0x083911A9",raw="20566f7564726169732d74752071757e32376f6e206372e96520756e650ae97175697065206465207365636f75727320656e73656d626c653f",text=" Voudrais-tu qu~27on crée une\néquipe de secours ensemble?"}},
    {index=82,address="0x0838DE0C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x0839102C",fr={block="0x0839102C",address="0x08391099",raw="20547520746520736f757669656e73206465206c610a63726576617373652064616e73206c617175656c6c6520246e3220610a63687574e93f",text=" Tu te souviens de la\ncrevasse dans laquelle $n2 a\nchuté?"}},
    {index=83,address="0x0838DE24",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08390E9C",fr={block="0x08390E9C",address="0x08390F29",raw="20506f757220756e6520726169736f6e20696e636f6e6e75657e32630a696c20792061206575206465206e6f6d6272657573657320636174617374726f706865730a6e61747572656c6c6573206475206dea6d65206f726472652072e963656d6d656e742e",text=" Pour une raison inconnue~2c\nil y a eu de nombreuses catastrophes\nnaturelles du même ordre récemment."}},
    {index=84,address="0x0838DE3C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08390D54",fr={block="0x08390D54",address="0x08390DC7",raw="2041206361757365206465206365730a636174617374726f706865737e32632062656175636f757020646520506f6be96d6f6e206f6e740a6265736f696e20647e3237616964652e",text=" A cause de ces\ncatastrophes~2c beaucoup de Pokémon ont\nbesoin d~27aide."}},
    {index=85,address="0x0838DE54",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08390C2C",fr={block="0x08390C2C",address="0x08390C94",raw="204a652076657578206169646572206c657320506f6be96d6f6e0ae0207375726d6f6e7465722063657320646966666963756c74e9732e",text=" Je veux aider les Pokémon\nà surmonter ces difficultés."}},
    {index=86,address="0x0838DE6C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08390AD0",fr={block="0x08390AD0",address="0x08390B60",raw="204a65207665757820666169726520656e20736f727465207175650a746f7573206c657320506f6be96d6f6e20766976656e7420656e20706169782e",text=" Je veux faire en sorte que\ntous les Pokémon vivent en paix."}},
    {index=87,address="0x0838DE84",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08390930",fr={block="0x08390930",address="0x083909DE",raw="20416c6f72737e3263206575682e2e2e23570a4568206269656e7e3263206a7e323761692061696de9207461206661e76f6e2064652072e9616769720a70656e64616e74206c652073617576657461676520646520246e322e",text=" Alors~2c euh...#W\nEh bien~2c j~27ai aimé ta façon de réagir\npendant le sauvetage de $n2."}},
    {index=88,address="0x0838DE9C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x08390818",fr={block="0x08390818",address="0x0839087F",raw="20566f7564726169732d7475207465206a6f696e64726520e0206d6f690a706f757220666f726d657220756e6520e97175697065206465207365636f7572733f",text=" Voudrais-tu te joindre à moi\npour former une équipe de secours?"}},
    {index=89,address="0x0838DEB4",op=244,arg_byte=0,arg_short=4,arg1=0,arg2=0,handler="flow.label",pointer=false},
    {index=90,address="0x0838DECC",op=46,arg_byte=21,arg_short=1,arg1=0,arg2=0,handler="portrait.set",pointer=false},
    {index=91,address="0x0838DEE4",op=216,arg_byte=1,arg_short=-1,arg1=1,arg2=40,handler="choice.ask_variable",pointer=false},
    {index=92,address="0x0838DEFC",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x08390678",fr={block="0x08390678",address="0x0839072B",raw="20246e307e3263206a652070656e73652071757e32376f6e0a666f726d6572616974206c61206d65696c6c6575726520e97175697065206465207365636f7572730a6175206d6f6e64652e2051757e3237656e2070656e7365732d74753f",text=" $n0~2c je pense qu~27on\nformerait la meilleure équipe de secours\nau monde. Qu~27en penses-tu?"}},
    {index=93,address="0x0838DF14",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x083904C0",fr={block="0x083904C0",address="0x08390576",raw="204a652070656e73652071757e32376f6e20706f7572726169740a646576656e6972206c61206d65696c6c6575726520e97175697065206465207365636f7572732061750a6d6f6e64657e326320246e302e2051757e3237656e206469732d74753f",text=" Je pense qu~27on pourrait\ndevenir la meilleure équipe de secours au\nmonde~2c $n0. Qu~27en dis-tu?"}},
    {index=94,address="0x0838DF2C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x083902F0",fr={block="0x083902F0",address="0x083903AF",raw="20246e307e3263206176656320746f697e32630a6f6e20706f757272616974206dea6d6520646576656e6972206c61206d65696c6c657572650ae97175697065206465207365636f757273206175206d6f6e64652e2051757e3237656e206469732d74753f",text=" $n0~2c avec toi~2c\non pourrait même devenir la meilleure\néquipe de secours au monde. Qu~27en dis-tu?"}},
    {index=95,address="0x0838DF44",op=217,arg_byte=0,arg_short=6,arg1=0,arg2=0,handler="choice.option",pointer="0x083902A0",fr={block="0x083902A0",address="0x083902CC",raw="4a7e3237616363657074652e",text="J~27accepte."}},
    {index=96,address="0x0838DF5C",op=217,arg_byte=0,arg_short=7,arg1=0,arg2=0,handler="choice.option",pointer="0x08390274",fr={block="0x08390274",address="0x08390286",raw="4a65207265667573652e",text="Je refuse."}},
    {index=97,address="0x0838DF74",op=244,arg_byte=0,arg_short=7,arg1=0,arg2=0,handler="flow.label",pointer=false},
    {index=98,address="0x0838DF8C",op=48,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.clear",pointer=false},
    {index=99,address="0x0838DFA4",op=219,arg_byte=0,arg_short=4,arg1=0,arg2=0,handler="timing.wait",pointer=false},
    {index=100,address="0x0838DFBC",op=13,arg_byte=2,arg_short=-1,arg1=0,arg2=0,handler="entities.select_lives",pointer=false},
    {index=101,address="0x0838DFD4",op=227,arg_byte=0,arg_short=5,arg1=0,arg2=0,handler="sync.await",pointer=false},
    {index=102,address="0x0838DFEC",op=69,arg_byte=0,arg_short=30,arg1=1,arg2=0,handler="audio.bgm_fadein",pointer=false},
    {index=103,address="0x0838E004",op=46,arg_byte=21,arg_short=1,arg1=12,arg2=0,handler="portrait.set",pointer=false},
    {index=104,address="0x0838E01C",op=207,arg_byte=2,arg_short=40,arg1=1,arg2=0,handler="dialogue.variable",pointer=false},
    {index=105,address="0x0838E034",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x083901F0",fr={block="0x083901F0",address="0x08390230",raw="2048756d3f204f687e3263206e6f6e7e326320616c6c657a21",text=" Hum? Oh~2c non~2c allez!"}},
    {index=106,address="0x0838E04C",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x0839015C",fr={block="0x0839015C",address="0x08390196",raw="204865696e3f204f687e3263206e6f6e7e326320737e3237696c20746520706c61ee7421",text=" Hein? Oh~2c non~2c s~27il te plaît!"}},
    {index=107,address="0x0838E064",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x083900FC",fr={block="0x083900FC",address="0x08390128",raw="204865696e3f204f687e3263206d6169732e2e2e",text=" Hein? Oh~2c mais..."}},
    {index=108,address="0x0838E07C",op=46,arg_byte=21,arg_short=1,arg1=5,arg2=0,handler="portrait.set",pointer=false},
    {index=109,address="0x0838E094",op=207,arg_byte=2,arg_short=40,arg1=1,arg2=0,handler="dialogue.variable",pointer=false},
    {index=110,address="0x0838E0AC",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x0838FFA4",fr={block="0x0838FFA4",address="0x08390037",raw="20246e307e326320696c20657374206365727461696e0a717565206e6f757320616c6c6f6e7320666169726520756e6520e9717569706520686f7273207061697221",text=" $n0~2c il est certain\nque nous allons faire une équipe hors pair!"}},
    {index=111,address="0x0838E0C4",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x0838FE1C",fr={block="0x0838FE1C",address="0x0838FEBF",raw="204d61697320656e66696e7e326320246e30210a456e73656d626c657e3263206e6f757320666f726d6572696f6e7320756e6520e971756970652064650a7365636f7572732073616e732070617265696c6c6521",text=" Mais enfin~2c $n0!\nEnsemble~2c nous formerions une équipe de\nsecours sans pareille!"}},
    {index=112,address="0x0838E0DC",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x0838FCB4",fr={block="0x0838FCB4",address="0x0838FD51",raw="20246e307e326320656e73656d626c65206e6f75730a666f726d6572696f6e7320756e6520e97175697065206465207365636f7572732064750a746f6e6e6572726521",text=" $n0~2c ensemble nous\nformerions une équipe de secours du\ntonnerre!"}},
    {index=113,address="0x0838E0F4",op=216,arg_byte=1,arg_short=-1,arg1=1,arg2=40,handler="choice.ask_variable",pointer=false},
    {index=114,address="0x0838E10C",op=208,arg_byte=0,arg_short=1,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x0838FB5C",fr={block="0x0838FB5C",address="0x0838FBFC",raw="20416c6f72737e3263206a6520747e3237656e2070726965210a4372e96f6e73206e6f74726520e97175697065206465207365636f75727321",text=" Alors~2c je t~27en prie!\nCréons notre équipe de secours!"}},
    {index=115,address="0x0838E124",op=208,arg_byte=0,arg_short=3,arg1=0,arg2=0,handler="dialogue.variant",pointer="0x0838FA10",fr={block="0x0838FA10",address="0x0838FA97",raw="20537e3237696c20746520706c61ee74210a566f7564726169732d747520666f726d657220756e6520e971756970652064650a7365636f7572732061766563206d6f693f",text=" S~27il te plaît!\nVoudrais-tu former une équipe de\nsecours avec moi?"}},
    {index=116,address="0x0838E13C",op=209,arg_byte=0,arg_short=0,arg1=0,arg2=0,handler="dialogue.variant_default",pointer="0x0838F8EC",fr={block="0x0838F8EC",address="0x0838F95D",raw="20416c6c657a7e326320737e3237696c20746520706c61ee742e0a4a652076657578206372e9657220756e6520e97175697065206465207365636f7572730a6176656320746f692e",text=" Allez~2c s~27il te plaît.\nJe veux créer une équipe de secours\navec toi."}},
