local BASE_PREFIX={
  {seq=1,index=6,address="0x0838D6EC",pointer="0x083939A0",text="Eh bien, on y est..."},
  {seq=2,index=24,address="0x0838D89C",pointer="0x08393978",text="(Waouh!)"},
  {seq=3,index=26,address="0x0838D8CC",pointer="0x08393898",text="(Je ne sais pas pourquoi,\nmais je me sens bien!)"},
  {seq=4,index=27,address="0x0838D8E4",pointer="0x08393710",text="(Je suis un humain, mais j'aime cet\nendroit. Je m'y sens étrangement bien!)"},
  {seq=5,index=30,address="0x0838D92C",pointer="0x08393390",text="(Ce doit être quelque chose d'instinctif\nchez les Pokémon...)"},
  {seq=6,index=32,address="0x0838D95C",pointer="0x08393240",text="(Si je m'écoutais, je sauterais dans tous\nles sens...)"},
  {seq=7,index=33,address="0x0838D974",pointer="0x08393194",text="(En tout cas, je me sens bien!)"},
  {seq=8,index=36,address="0x0838D9BC",pointer="0x08392EA4",text="(Peut-être que je ressens ça parce que je\nsuis $m0!)"},
  {seq=9,index=43,address="0x0838DA64",pointer="0x08392DAC",text="Alors? $n0.\nJe vois que ça t'impressionne."},
  {seq=10,index=46,address="0x0838DAAC",pointer="0x08392B40",text="Je me doutais que cet\nendroit te plairait."},
  {seq=11,index=61,address="0x0838DC14",pointer="0x08392404",text="Ça, c'est ta [color=#00FFFF]Boîte aux\nlettres[color].[pause=30] Tu y recevras des lettres\nd'autres Pokémon."},
  {seq=12,index=68,address="0x0838DCBC",pointer="0x08392120",text="Tu te rappelles cette\ncrevasse dans laquelle $n2 est\ntombé?"},
  {seq=13,index=69,address="0x0838DCD4",pointer="0x08391FDC",text="Il y a plein d'autres\ncatastrophes naturelles de ce type en ce\nmoment."},
  {seq=14,index=70,address="0x0838DCEC",pointer="0x08391EA8",text="De nombreux Pokémon\nsouffrent de ces catastrophes."},
  {seq=15,index=71,address="0x0838DD04",pointer="0x08391DEC",text="Et moi, je veux aider ces\nPokémon."},
  {seq=16,index=72,address="0x0838DD1C",pointer="0x08391C8C",text="Je veux aider à faire de ce\nmonde un lieu où tous les Pokémon\npuissent vivre en sécurité."},
  {seq=17,index=73,address="0x0838DD34",pointer="0x08391AC0",text="Et, euh...[pause=30] après avoir vu\ncomment tu as secouru $n2, je\ncrois que tu pourrais m'aider."},
  {seq=18,index=74,address="0x0838DD4C",pointer="0x083919C0",text="Ça te dirait de monter une\néquipe de secours avec moi?"},
  {seq=19,index=92,address="0x0838DEFC",pointer="0x08390678",text="$n0, je pense qu'on\nformerait la meilleure équipe de secours\nau monde. Qu'en penses-tu?"}
}
